export type WeeklyLearningGoalMetric = "study_days" | "lessons" | "attendance" | "practice_hours";
const weeklyGoalMetrics = new Set<WeeklyLearningGoalMetric>(["study_days", "lessons", "attendance", "practice_hours"]);
type StoredAgreementInstallment = { installment_number: number; amount: number; due_on: string };
export function projectStoredAgreementSchedule(installments: StoredAgreementInstallment[], coveredAmount: number, currency: string, now = Date.now()) {
  let remainingCoverage = Math.max(0, Math.round(coveredAmount * 100));
  return installments.map((entry) => {
    const amountCents = Math.round(Number(entry.amount) * 100);
    const coveredCents = Math.min(remainingCoverage, amountCents);
    remainingCoverage -= coveredCents;
    const dueAt = new Date(`${String(entry.due_on).slice(0, 10)}T12:00:00.000Z`).toISOString();
    return { number: entry.installment_number, amount: amountCents / 100, covered_amount: coveredCents / 100, currency, due_at: dueAt,
      status: coveredCents >= amountCents ? "paid" as const : coveredCents > 0 ? "partial" as const
        : Date.parse(dueAt) < now ? "overdue" as const : "upcoming" as const };
  });
}
export function summarizeStoredAgreementArrears(installments: StoredAgreementInstallment[], coveredAmount: number, currency: string, now = Date.now()) {
  const overdue = projectStoredAgreementSchedule(installments, coveredAmount, currency, now)
    .filter((installment) => Date.parse(installment.due_at) < now && installment.amount > installment.covered_amount)
    .map((installment) => ({ due_at: installment.due_at,
      remaining_cents: Math.max(0, Math.round((installment.amount - installment.covered_amount) * 100)) }));
  return { overdue_installment_count: overdue.length, overdue_balance: overdue.reduce((sum, row) => sum + row.remaining_cents, 0) / 100,
    oldest_overdue_at: overdue[0]?.due_at || null };
}
export function postAgreementCoverage(entries: Array<{ paid_at?: unknown; payment_method?: unknown; amount?: unknown }>, effectiveAt: string) {
  const effective = Date.parse(effectiveAt);
  if (!Number.isFinite(effective)) return 0;
  const cents = entries.reduce((sum, entry) => {
    const paidAt = Date.parse(String(entry.paid_at || ""));
    if (!Number.isFinite(paidAt) || paidAt < effective) return sum;
    const amountCents = Math.max(0, Math.round(Number(entry.amount || 0) * 100));
    return sum + (entry.payment_method === "refund" ? -amountCents : amountCents);
  }, 0);
  return Math.max(0, cents) / 100;
}
function validWeeklyGoalTarget(metric: WeeklyLearningGoalMetric, value: number) {
  if (!Number.isFinite(value)) return false;
  if (metric === "study_days" || metric === "attendance") return Number.isInteger(value) && value >= 1 && value <= 7;
  if (metric === "lessons") return Number.isInteger(value) && value >= 1 && value <= 21;
  return value >= 0.5 && value <= 40 && Math.round(value * 2) === value * 2;
}
export function normalizeWeeklyLearningGoal(body: Payload, existing: Payload = {}) {
  const existingMetric = weeklyGoalMetrics.has(existing.weekly_learning_goal_metric as WeeklyLearningGoalMetric)
    ? existing.weekly_learning_goal_metric as WeeklyLearningGoalMetric : "study_days";
  const metric = weeklyGoalMetrics.has(body.weekly_learning_goal_metric as WeeklyLearningGoalMetric)
    ? body.weekly_learning_goal_metric as WeeklyLearningGoalMetric : existingMetric;
  const requestedTarget = Number(body.weekly_learning_goal_target);
  const savedTarget = Number(existing.weekly_learning_goal_target);
  const legacyDays = Number(body.weekly_learning_goal_days ?? existing.weekly_learning_goal_days ?? 3);
  const defaultTarget = metric === "study_days" ? legacyDays : metric === "attendance" ? 1 : metric === "practice_hours" ? 2 : 3;
  const target = validWeeklyGoalTarget(metric, requestedTarget) ? requestedTarget
    : metric === existingMetric && validWeeklyGoalTarget(metric, savedTarget) ? savedTarget
      : validWeeklyGoalTarget(metric, defaultTarget) ? defaultTarget : metric === "practice_hours" ? 2 : 3;
  return { metric, target };
}
export function calculateWeeklyLearningGoal(metricInput: string, activityRows: Array<{ activity_day: string; activity_metric: string; activity_value: number }>,
  weekStart: string, today: string, requestedTarget: number, legacyDays = 3) {
  const metric = weeklyGoalMetrics.has(metricInput as WeeklyLearningGoalMetric) ? metricInput as WeeklyLearningGoalMetric : "study_days";
  const weekRows = activityRows.filter((row) => {
    const day = new Date(row.activity_day).toISOString().slice(0, 10);
    return day >= weekStart && day <= today;
  });
  const activeDays = new Set(weekRows.map((row) => new Date(row.activity_day).toISOString().slice(0, 10))).size;
  const fallback = metric === "study_days" ? legacyDays : metric === "attendance" ? 1 : metric === "practice_hours" ? 2 : 3;
  const target = validWeeklyGoalTarget(metric, requestedTarget) ? requestedTarget
    : validWeeklyGoalTarget(metric, fallback) ? fallback : 3;
  const current = metric === "study_days" ? activeDays
    : metric === "lessons" ? weekRows.filter((row) => row.activity_metric === "lessons").length
      : metric === "attendance" ? weekRows.filter((row) => row.activity_metric === "attendance").length
        : weekRows.filter((row) => row.activity_metric === "practice_hours").reduce((sum, row) => sum + Number(row.activity_value || 0), 0);
  const unit = metric === "study_days" ? "dias ativos" : metric === "lessons" ? "aulas"
    : metric === "attendance" ? "presenças" : "horas práticas";
  return { metric, activeDays, current: Number(current.toFixed(1)), target, unit, percent: Math.min(100, Math.round(current / target * 100)) };
}
export function allocatePracticeCredit(requestedHours: number, practices: Array<{ id: string; hours_validated: number; credited_hours: number }>) {
  if (!Number.isFinite(requestedHours) || requestedHours <= 0) return null;
  let remaining = Math.round(requestedHours * 100) / 100;
  const allocations: Array<{ practice_record_id: string; hours_credited: number }> = [];
  for (const practice of [...practices].sort((a, b) => a.id.localeCompare(b.id))) {
    const available = Math.max(0, Number(practice.hours_validated) - Number(practice.credited_hours));
    const allocated = Math.min(available, remaining);
    if (allocated > 0) allocations.push({ practice_record_id: practice.id, hours_credited: Math.round(allocated * 100) / 100 });
    remaining = Math.round((remaining - allocated) * 100) / 100;
    if (remaining <= 0) return allocations;
  }
  return null;
}
export function calculateWorkloadProgress(attendedMinutes: number, validatedPracticeHours: number, creditedPracticeHours = 0) {
  const safe = (value: number) => Number.isFinite(value) && value > 0 ? value : 0;
  const attendedClassHours = safe(attendedMinutes) / 60;
  const validated = safe(validatedPracticeHours);
  const credited = safe(creditedPracticeHours);
  return {
    attended_class_hours: Math.round(attendedClassHours * 100) / 100,
    validated_practice_hours: Math.round(validated * 100) / 100,
    credited_practice_hours: Math.round(credited * 100) / 100,
    completed_hours: Math.round((attendedClassHours + validated + credited) * 100) / 100,
  };
}
const PRIVACY_SUBJECT_ID_FIELDS = new Set([
  "learner_user_id", "staff_user_id", "owner_user_id", "author_user_id", "requester_user_id",
  "reporter_user_id", "sender_user_id", "recipient_user_id", "terms_signature_user_id", "teacher_user_id", "user_id",
  "group_member_user_ids",
]);
const PRIVACY_NON_REDACTABLE_FIELDS = new Set([
  "id", "workspace_id", "created_at", "updated_at", "actor_id", "user_id", "learner_user_id", "staff_user_id",
  "owner_user_id", "author_user_id", "requester_user_id", "reporter_user_id", "sender_user_id", "recipient_user_id",
  "terms_signature_user_id", "teacher_user_id", "group_member_user_ids", "grade", "score", "attendance", "minutes_attended",
  "certificate_code", "protocol_number", "result",
]);
export function privacyPathIsAllowedForErasure(path: string[]) {
  return path.length > 0 && path.every((part) => !PRIVACY_NON_REDACTABLE_FIELDS.has(part) && !part.endsWith("_record_id"));
}
function collectPrivacySubjectIds(value: unknown, result = new Set<string>()): Set<string> {
  if (!value || typeof value !== "object") return result;
  if (Array.isArray(value)) { for (const item of value) collectPrivacySubjectIds(item, result); return result; }
  for (const [key, item] of Object.entries(value as Record<string, unknown>)) {
    if (PRIVACY_SUBJECT_ID_FIELDS.has(key)) {
      if (typeof item === "string" && item.trim()) result.add(item.toLowerCase());
      else if (Array.isArray(item)) for (const userId of item)
        if (typeof userId === "string" && userId.trim()) result.add(userId.toLowerCase());
    } else collectPrivacySubjectIds(item, result);
  }
  return result;
}
function hasLinkedRecordReference(value: unknown, recordIds: Set<string>): boolean {
  if (!value || typeof value !== "object") return false;
  if (Array.isArray(value)) return value.some((item) => hasLinkedRecordReference(item, recordIds));
  return Object.entries(value as Record<string, unknown>).some(([key, item]) =>
    key.endsWith("_record_id") && typeof item === "string" && recordIds.has(item.toLowerCase())
      || hasLinkedRecordReference(item, recordIds));
}
type PrivacyInventoryRecord = { id: string; payload: Payload };
type PrivacyInventoryVersion = { record_id: string; payload: Payload };
export function privacyRelatedRecordIds(
  subjectId: string,
  records: PrivacyInventoryRecord[],
  versions: PrivacyInventoryVersion[],
): Set<string> {
  const normalizedSubject = subjectId.toLowerCase();
  const versionsByRecord = new Map<string, Payload[]>();
  for (const version of versions) versionsByRecord.set(version.record_id, [...versionsByRecord.get(version.record_id) || [], version.payload]);
  const recordOwnerIds = (record: PrivacyInventoryRecord) => {
    const owners = collectPrivacySubjectIds(record.payload);
    for (const payload of versionsByRecord.get(record.id) || []) collectPrivacySubjectIds(payload, owners);
    return owners;
  };
  const related = new Set(records.filter((record) => recordOwnerIds(record).has(normalizedSubject)).map((record) => record.id));
  const expanded = new Set([...related].filter((recordId) => {
    const record = records.find((candidate) => candidate.id === recordId)!;
    const owners = recordOwnerIds(record);
    return owners.size === 1 && owners.has(normalizedSubject);
  }));
  let changed = true;
  while (changed) {
    changed = false;
    for (const record of records) {
      if (related.has(record.id)) continue;
      const recordPayloads = [record.payload, ...(versionsByRecord.get(record.id) || [])];
      if (!recordPayloads.some((payload) => hasLinkedRecordReference(payload, expanded))) continue;
      related.add(record.id);
      changed = true;
      const owners = recordOwnerIds(record);
      // Shared and ownerless descendants require an explicit preserve mapping and
      // never become graph vertices; this prevents traversal into other learners' data.
      if (owners.size === 1 && owners.has(normalizedSubject)) expanded.add(record.id);
    }
  }
  return related;
}
export function privacyRecordOwnership(subjectId: string, payloads: unknown[]): "owned" | "shared" | "other" | "unowned" {
  const owners = new Set<string>();
  for (const payload of payloads) collectPrivacySubjectIds(payload, owners);
  const normalizedSubject = subjectId.toLowerCase();
  if (owners.has(normalizedSubject)) return owners.size === 1 ? "owned" : "shared";
  return owners.size ? "other" : "unowned";
}
export function privacyMappingKey(pluginId: string | undefined, recordKind: string) {
  return `${pluginId || "suinda-learning"}:${recordKind}`;
}
export function privacyPathExists(value: unknown, path: string[]) {
  let current = value;
  for (const key of path) {
    if (!current || typeof current !== "object" || Array.isArray(current) || !(key in current)) return false;
    current = (current as Record<string, unknown>)[key];
  }
  return true;
}
export function privacyPathIsRedactableLeaf(value: unknown, path: string[]) {
  if (!path.length) return false;
  let current = value;
  for (let index = 0; index < path.length; index++) {
    if (!current || typeof current !== "object" || Array.isArray(current) || !(path[index] in current)) return false;
    current = (current as Record<string, unknown>)[path[index]];
    if (index < path.length - 1 && (!current || typeof current !== "object" || Array.isArray(current))) return false;
  }
  return current === null || typeof current !== "object";
}
