const PRIVACY_ACCOUNT_SHARED_IDENTITY_SQL = `SELECT
  EXISTS(SELECT 1 FROM workspace_members WHERE user_id=$1 AND (workspace_id<>$2 OR can_manage))
  OR EXISTS(SELECT 1 FROM access_grants WHERE user_id=$1 AND role_id<>'user')
  OR EXISTS(SELECT 1 FROM access_group_members WHERE user_id=$1)
  OR EXISTS(SELECT 1 FROM access_user_exceptions WHERE user_id=$1)
  OR EXISTS(SELECT 1 FROM extension_records WHERE plugin_id='suinda-learning' AND payload->>'staff_user_id'=$1)
  OR EXISTS(SELECT 1 FROM extension_records WHERE (plugin_id<>'suinda-learning' OR workspace_id<>$2)
    AND payload::text LIKE ('%'||to_jsonb($1::text)::text||'%')) AS shared`;
function redactJsonPath(value: Payload, path: string[]): Payload {
  const result = structuredClone(value);
  let current: Payload = result;
  for (const part of path.slice(0, -1)) current = current[part] as Payload;
  delete current[path[path.length - 1]];
  return result;
}
export function privacyIdentityChallengeIsUsable(row: {
  consumed_at: unknown; email_verified: boolean; disabled: boolean; is_root: boolean;
  challenge_session_version: number; session_version: number; attempts: number; expires_at: Date | string;
}, now = Date.now()) {
  return !row.consumed_at && row.email_verified && !row.disabled && !row.is_root
    && row.challenge_session_version === row.session_version && row.attempts < 5
    && new Date(row.expires_at).getTime() > now;
}
export function privacyCategoryDecisionGaps(categories: string[], decisions: Array<{ category: string; decision: string }>) {
  const latest = new Map(decisions.map((decision) => [decision.category, decision.decision]));
  return { missing: categories.filter((category) => !latest.has(category)), denied: categories.filter((category) => latest.get(category) !== "approved") };
}
